_parking":0},{"peak_slug":"lubomir","id":31,"peak_id":21,"slug":"lubomir-katalog-03","start_point_name":"W\u0119gl\u00f3wka","end_point_name":"Lubomir \u2013 obserwatorium","expected_parking":0},{"peak_slug":"mogielica","id":32,"peak_id":22,"slug":"mogielica-katalog-03","start_point_name":"Tymbark PKP","end_point_name":"Mogielica","expected_parking":0},{"peak_slug":"czupel","id":33,"peak_id":24,"slug":"czupel-katalog-03","start_point_name":"Czernich\u00f3w","end_point_name":"Mi\u0119dzybrodzie Bialskie","expected_parking":1},{"peak_slug":"skrzyczne","id":34,"peak_id":25,"slug":"skrzyczne-katalog-03","start_point_name":"Ostre \u2013 parking przy ul. S\u0142onecznej","end_point_name":"Ostre \u2013 parking przy ul. S\u0142onecznej","expected_parking":1},{"peak_slug":"wysoka-pieniny","id":35,"peak_id":26,"slug":"wysoka-pieniny-katalog-03","start_point_name":"Jaworki","end_point_name":"Uroczysko Zaskalskie","expected_parking":0},{"peak_slug":"rysy","id":36,"peak_id":16,"slug":"rysy-palenica-czerwony-wejscie","start_point_name":"Palenica Bia\u0142cza\u0144ska","end_point_name":"Rysy","expected_parking":1},{"peak_slug":"lackowa","id":37,"peak_id":23,"slug":"lackowa-izby-zolty-wejscie","start_point_name":"Izby","end_point_name":"Lackowa","expected_parking":0},{"peak_slug":"wysoka-kopa","id":38,"peak_id":3,"slug":"wysoka-kopa-sine-skalki-czerwony-odcinek","start_point_name":"Rozdro\u017ce pod Izerskimi Garbami","end_point_name":"Sine Ska\u0142ki","expected_parking":0}]$targets$::jsonb))
select e->>'peak_slug' peak_slug,t.slug,
 (select count(*) from public.trail_access a where a.trail_id=t.id and a.active) access_cards,
 (select count(*) from public.trail_access_i18n i join public.trail_access a on a.id=i.access_id where a.trail_id=t.id and a.active) access_translations,
 (select count(*) from public.trail_parking p where p.trail_id=t.id and p.active) parking_cards,
 (e->>'expected_parking')::integer expected_parking_cards,
 (select count(*) from public.trail_parking_i18n i join public.trail_parking p on p.id=i.parking_id where p.trail_id=t.id and p.active) parking_translations,
 t.active and k.active and k.is_korona and k.slug=e->>'peak_slug' and t.peak_id=(e->>'peak_id')::bigint
  and t.start_point_name is not distinct from e->>'start_point_name' and t.end_point_name is not distinct from e->>'end_point_name' route_identity_matches
from targets left join public.trails t on t.id=(e->>'id')::bigint and t.slug=e->>'slug'
 left join public.peaks k on k.id=t.peak_id order by e->>'peak_slug';
